examples.css:
/* element selector */
h1 { color: #ff3368; }
/* class selector */
.para { color: #ff00ff; }
/* id selector + hover state */
#btn { background-color: #ff3368; color: #fff; padding: 6px 14px; text-decoration: none; border-radius: 4px; }
#btn:hover { background-color: black; color: white; }
h1:hover { color: blue; }

body { font-family: sans-serif; }
h1, h2 { color: #0f2c59; }
.note { background: #fff3cd; padding: 8px; margin: 6px 0; }
#special { border-left: 5px solid crimson; }

body { font-family: sans-serif; }
a { display: inline-block; margin: 4px 0; }
a[href^="https"] { color: green; }
a[href$=".pdf"]::after { content: " (PDF)"; color: crimson; }
input[type="checkbox"] { accent-color: hotpink; width: 20px; height: 20px; }

.row { display: flex; gap: 6px; font: 12px sans-serif; color: #fff; }
.sw { width: 70px; height: 70px; display: grid; place-items: center; border-radius: 8px;
  background-image: linear-gradient(45deg,#ccc 25%,#fff 25% 50%,#ccc 50% 75%,#fff 75%); background-size: 16px 16px; }
.a { background-color: red; }
.b { background-color: #ff0000; }
.c { background-color: rgb(255, 0, 0); }
.d { background-color: rgba(255, 0, 0, 0.5); }
.e { background-color: hsl(0, 100%, 50%); }
.f { background-color: hsl(0 100% 50% / 0.5); }

.card { color: hsl(226 84% 35%); border: 3px solid currentColor; padding: 12px; font-family: sans-serif; width: 220px; border-radius: 8px; }
button { background: hsl(226 84% 50%); color: #fff; border: 0; padding: 8px 14px; border-radius: 6px; }
button.dark { background: hsl(226 84% 30%); }

.parent { font-size: 10px; font-family: sans-serif; background: #eef; padding: 10px; }
.em { font-size: 2em; }
.rem { font-size: 2rem; }

.box { color: #0d6efd; font: 18px/1.5 Georgia, serif; border: 3px solid #0d6efd; padding: 10px; }
.own { color: crimson; }
.inner { background: #eef; }

.parent { color: green; border: 2px dashed green; padding: 8px; font-family: sans-serif; }
span { border: 1px solid; margin-right: 8px; padding: 2px 6px; }
.a { color: inherit; }
.b { color: initial; }   /* black (spec default) */
.c { color: unset; }     /* color is inherited, so green */

h1 { color: red; }                          /* 0,0,1 */
.hero-content h1 { color: orange; }          /* 0,1,1 */
.heading { color: green; }                   /* 0,1,0 */
#title { color: royalblue; }                 /* 1,0,0  <- wins */
/* h1 { color: pink !important; }  uncomment to see !important win */
h1 { font: bold 32px sans-serif; }

a { font: 20px sans-serif; }
:where(.menu) a { color: purple; }  /* specificity 0,0,1 */
.menu a { color: darkgreen; }        /* 0,1,1 - wins easily */
